 out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><meta name="description" content="{html.escape(desc,quote=True)}"><link rel="canonical" href="{url}"><meta property="og:title" content="{html.escape(title,quote=True)}"><meta property="og:description" content="{html.escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}/assets/hero.jpg"><meta name="twitter:card" content="summary_large_image"><meta name="theme-color" content="#202c2b"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.css"><script type="application/ld+json">{json.dumps(schema)}</script><script src="/assets/site.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header><div class="nav wrap"><a class="wordmark" href="/">JAMES NOWLIN<span>REALTY ONE GROUP RESIDE</span></a><button class="menu" aria-label="Open navigation" aria-expanded="false" aria-controls="navlinks">Menu ☰</button><nav id="navlinks" aria-label="Main navigation">{nav}{btn('Let’s talk','/contact/','small')}</nav></div></header><main id="main">{body}{cta()}</main><footer><div class="wrap footgrid"><div><a class="wordmark" href="/">JAMES NOWLIN<span>REALTY ONE GROUP RESIDE</span></a><p>Real estate. Personal attention.<br>Columbia & the South Carolina Midlands.</p><img class="brokerlogo" src="/assets/logo.png" alt="Realty ONE Group Reside" loading="lazy"></div><div><h3>Find your next chapter</h3><a href="/homes/">Search homes</a><a href="/areas/">Explore the Midlands</a><a href="/buy/">Buying a home</a><a href="/sell/">Selling your home</a><a href="/resources/">Local resources</a><a href="/faq/">Questions, answered</a></div><div><h3>Connect with James</h3><a href="tel:+18039490229">(803) 949-0229</a><a href="mailto:office@jamesnowlinrealtor.com">office@jamesnowlinrealtor.com</a><p>5300-B Sunset Blvd.<br>Lexington, SC 29072<br>SC License #129577</p><a href="https://www.instagram.com/jamesnowlinsc/">Instagram ↗</a><a href="https://www.facebook.com/JamesNowlinRealtor/">Facebook ↗</a></div></div><div class="wrap legal">© 2026 James Nowlin · Realty ONE Group Reside. Equal Housing Opportunity.<br>Property information is subject to change. Verify availability and details with the listing brokerage. Hero photograph is illustrative and is not an advertised listing.<div><a href="/privacy/">Privacy</a> · <a href="/sources/">Information & sources</a> · <a href="{OLD}/accessibility-policy">Accessibility</a></div></div></footer><div class="mobilebar"><a href="tel:+18039490229">Call James</a><a href="/homes/">Search homes ↗</a></div></body></html>'''
 prefix=urlsplit(BASE).path.rstrip('/')
 if prefix:out=re.sub(r'(href|src)="/(?!/)',lambda m:m.group(1)+'="'+prefix+'/',out)
 target=D/path.strip('/')/'index.html';target.parent.mkdir(parents=True,exist_ok=True);target.write_text(out);pages[path]=(title,desc)
