page('/areas/','Columbia Area & Lake Murray Community Guides | James Nowlin','Compare six Midlands home-search areas, with practical questions for Columbia, Lexington, Irmo, Chapin, Lake Murray, West Columbia and Cayce.',intro('FIND YOUR PLACE','A region of possibilities.','Explore six starting points for your Midlands home search. Use these guides to compare location, daily routines, and property details—not just a pin on a map.')+'<section class="wrap section topzero">'+area_cards()+'</section>')
for s,n,h,tag,overview,homes,check,life,source in areas:
 f=[(f'What should I compare when looking at homes in {n}?',homes),(f'What should I verify before buying in {n}?',check)]
 content=intro('THE MIDLANDS / '+n.upper(),h,overview)+f'<section class="wrap guide"><div class="guidebody"><h2>Buying a home in {n}</h2><p>{homes}</p><h2>Think beyond the front door.</h2><p>{life}</p><h2>Details worth a closer look.</h2><p>{check}</p><p>For any property, verify school assignments directly with the district and inspect the home’s condition. Choose a location based on your own needs and firsthand visits.</p><h2>Your {n} questions, answered.</h2>'+faqblock(f)+f'<p class="fine">Local orientation: <a href="{source}">official community or visitor resource ↗</a>. Guide reviewed October 14, 2026. This is a search-planning guide, not a market-price report.</p></div><aside><p class="eyebrow">MAKE IT PERSONAL</p><h3>Let’s narrow<br>the search.</h3><p>Share your budget, must-haves, and daily destinations with James.</p>'+btn('Talk about '+n,'/contact/')+btn('Open property search',SEARCH,'light')+'<p class="fine">Use location filters in James’s brokerage search.</p><a href="/areas/">← Compare all areas</a></aside></section><section class="wrap section"><h2>Keep exploring.</h2><div class="chips">'+''.join(f'<a href="/areas/{sl}/">{nm} ↗</a>' for sl,nm,*_ in areas if sl!=s)+'</div></section>'
 page('/areas/'+s+'/',f'{n} SC Real Estate & Home Buying Guide | James Nowlin',f'Explore {n} real estate with James Nowlin. Compare home-search priorities, daily-life considerations and property details before your next move.',content,f)
page('/about/','Meet James Nowlin | Columbia SC Real Estate Agent','Meet James Nowlin of Realty ONE Group Reside: personal service, a mortgage-finance background and a detail-focused approach to Columbia-area real estate.',intro('A PERSONAL APPROACH','Meet James.','Real estate guidance built around your goals.')+'<section class="wrap split section topzero"><div class="portraitframe"><img src="/assets/portrait.png" alt="James Nowlin" width="319" height="319"><span>JAMES NOWLIN · SC LICENSE #129577</span></div><div><h2>The person behind<br><em>your next move.</em></h2><p>James Nowlin is a real estate agent with Realty ONE Group Reside in the Columbia metro area. His background in mortgage finance informs his attention to detail, problem-solving, and communication.</p><p>His approach starts with understanding what a successful move looks like for you. Whether you are searching for a home or preparing to sell, the goal is a personalized plan and clear next steps.</p><p>Explore the Midlands guides, bring your questions, and start a conversation about what comes next.</p>'+btn('Connect with James','/contact/')+'</div></section>')
for kind,heading,sub,steps in [('buy','A home that fits your life.','Start with what matters. Build a plan. Find your next chapter.', [('Start with your priorities','Share your budget, timing, daily destinations, and non-negotiables. Distinguish what you need from what would simply be nice to have.'),('Get your financing picture clear','Talk with a qualified lender about your options and documentation before making commitments. James’s mortgage-finance background can help frame the questions to ask.'),('Explore, compare, and tour','Use the area guides and brokerage search to build a shortlist. Compare the full property, its condition, and the location—not just photographs.'),('Move forward with a plan','Discuss an offer, inspections, deadlines, and closing steps with James and the appropriate professionals. Each transaction has its own terms and timeline.')]),('sell','Your next chapter starts here.','A thoughtful sale begins before the listing goes live.', [('Talk about your goals','Begin with your reason for selling, preferred timing, and what comes next. If you are also buying, discuss both sides of the move together.'),('Understand your home’s position','Review relevant comparable sales, current competition, property condition, and location with James. A pricing discussion should be specific to your home.'),('Prepare to make an impression','Walk through repairs, decluttering, presentation, and photography priorities. Focus on preparation that makes sense for the property and your budget.'),('Evaluate offers and next steps','Compare terms as well as price. Discuss contingencies, timing, and the path from an accepted offer to closing before choosing how to proceed.')])]:
 body=intro('YOUR GUIDE TO '+kind.upper()+'ING',heading,sub)+'<section class="wrap guide"><div class="steps">'+''.join(f'<article><span>0{i+1}</span><div><h2>{h}</h2><p>{t}</p></div></article>' for i,(h,t) in enumerate(steps))+'</div><aside><p class="eyebrow">START A CONVERSATION</p><h3>'+('What are you<br>looking for?' if kind=='buy' else 'What’s your<br>home worth?')+'</h3><p>Tell James a little about your plans. Get a clear next step.</p>'+btn('Talk with James','/contact/')+btn('Search available homes' if kind=='buy' else 'Get a home-value estimate',SEARCH if kind=='buy' else OLD+'/my-home-value','light')+'</aside></section>'
 page('/'+kind+'/',('Buy a Home' if kind=='buy' else 'Sell Your Home')+' in Columbia SC | James Nowlin',sub+' Connect with James Nowlin of Realty ONE Group Reside in the Columbia metro area.',body)
page('/homes/','Search Columbia SC & Midlands Homes | James Nowlin','Open James Nowlin’s brokerage home search for current listings across Columbia and the Midlands, or explore his featured and historical listings.',intro('FIND YOUR NEXT HOME','Your search starts here.','Explore current listings through James’s Realty ONE Group property search. Use its location, price, and property filters to make the search your own.')+'<section class="wrap section topzero"><div class="searchpanel"><p class="eyebrow">CONNECTED TO JAMES’S BROKERAGE</p><h2>Fresh possibilities.<br><em>One place to look.</em></h2><p>Open the brokerage search for current property information and showing options.</p>'+btn('Open live property search',SEARCH,'gold')+'<div class="chips"><a href="'+OLD+'/my-featured-listings">James’s featured listings ↗</a><a href="'+OLD+'/my-sold-properties">Brokerage sold-property archive ↗</a></div><p class="fine">Opens the existing brokerage website. Some features may require an account. This website does not display a live MLS feed.</p></div></section>')
