(D/'assets/site.js').write_text('''const menu=document.querySelector('.menu'),nav=document.querySelector('#navlinks');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}});const form=document.querySelector('#contactform');if(form)form.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form);const body='Name: '+d.get('name')+'\\nEmail: '+d.get('email')+'\\nInterest: '+d.get('interest')+'\\n\\n'+d.get('message');location.href='mailto:office@jamesnowlinrealtor.com?subject='+encodeURIComponent('Real estate inquiry: '+d.get('interest'))+'&body='+encodeURIComponent(body);document.querySelector('#formstatus').textContent='Your email app should open with a draft. Review and send it there. If it does not open, email office@jamesnowlinrealtor.com or call (803) 949-0229.'});''')
